-- Pregunta 1: Escala 1-5 (ambiente de trabajo) INSERT INTO public.k_survey_question (tenant_id, id_survey, ds_question, ds_type, ds_options, nb_order, fg_required, fg_active, dt_creation_date) SELECT 'demo-corp', id_survey, '¿Cómo calificarías el ambiente de trabajo en tu área? (1=Muy malo, 5=Excelente)', 'ESCALA', '1,2,3,4,5', 1, true, true, NOW() FROM public.k_survey WHERE tenant_id = 'demo-corp' AND ds_title = 'Clima Laboral Q3 2026';
-- Pregunta 2: Opción múltiple (retroalimentación) INSERT INTO public.k_survey_question (tenant_id, id_survey, ds_question, ds_type, ds_options, nb_order, fg_required, fg_active, dt_creation_date) SELECT 'demo-corp', id_survey, '¿Tu jefe directo te da retroalimentación clara y oportuna?', 'OPCION_MULTIPLE', 'Siempre,Frecuentemente,A veces,Casi nunca,Nunca', 2, true, true, NOW() FROM public.k_survey WHERE tenant_id = 'demo-corp' AND ds_title = 'Clima Laboral Q3 2026';
-- Pregunta 3: Texto libre (sugerencias) INSERT INTO public.k_survey_question (tenant_id, id_survey, ds_question, ds_type, nb_order, fg_required, fg_active, dt_creation_date) SELECT 'demo-corp', id_survey, '¿Qué mejora sugerirías para el equipo o la empresa? (opcional)', 'TEXTO_LIBRE', 3, false, true, NOW() FROM public.k_survey WHERE tenant_id = 'demo-corp' AND ds_title = 'Clima Laboral Q3 2026';

