-- Candidato 1 (Sofía): POSTULADO → ENTREVISTA INSERT INTO public.k_pipeline_stage (tenant_id, id_candidate, ds_stage, dt_stage_date, ds_notes, ds_created_by, fg_active, dt_creation_date) SELECT 'demo-corp', id_candidate, 'POSTULADO', NOW() - INTERVAL '10 days', 'Postulación recibida vía LinkedIn', 'rrhh@dch.mx', true, NOW() FROM public.k_candidate WHERE tenant_id = 'demo-corp' AND ds_email = 'candidato1.demo@gmail.com';
INSERT INTO public.k_pipeline_stage (tenant_id, id_candidate, ds_stage, dt_stage_date, ds_notes, ds_created_by, fg_active, dt_creation_date) SELECT 'demo-corp', id_candidate, 'ENTREVISTA', NOW() - INTERVAL '7 days', 'CV aprobado. Entrevista telefónica agendada para el lunes.', 'rrhh@dch.mx', true, NOW() FROM public.k_candidate WHERE tenant_id = 'demo-corp' AND ds_email = 'candidato1.demo@gmail.com';
-- Candidato 2 (Miguel): POSTULADO → ENTREVISTA → SELECCIONADO INSERT INTO public.k_pipeline_stage (tenant_id, id_candidate, ds_stage, dt_stage_date, ds_notes, ds_created_by, fg_active, dt_creation_date) SELECT 'demo-corp', id_candidate, 'POSTULADO', NOW() - INTERVAL '20 days', 'Referido por empleado interno — perfil validado', 'rrhh@dch.mx', true, NOW() FROM public.k_candidate WHERE tenant_id = 'demo-corp' AND ds_email = 'candidato2.demo@hotmail.com';
INSERT INTO public.k_pipeline_stage (tenant_id, id_candidate, ds_stage, dt_stage_date, ds_notes, ds_created_by, fg_active, dt_creation_date) SELECT 'demo-corp', id_candidate, 'ENTREVISTA', NOW() - INTERVAL '15 days', 'Entrevista presencial con área técnica y RRHH exitosa', 'rrhh@dch.mx', true, NOW() FROM public.k_candidate WHERE tenant_id = 'demo-corp' AND ds_email = 'candidato2.demo@hotmail.com';
INSERT INTO public.k_pipeline_stage (tenant_id, id_candidate, ds_stage, dt_stage_date, ds_notes, ds_created_by, fg_active, dt_creation_date) SELECT 'demo-corp', id_candidate, 'SELECCIONADO', NOW() - INTERVAL '10 days', 'Candidato seleccionado. Pendiente expediente digital.', 'rrhh@dch.mx', true, NOW() FROM public.k_candidate WHERE tenant_id = 'demo-corp' AND ds_email = 'candidato2.demo@hotmail.com';
-- Candidato 3 (Lucía): POSTULADO → ENTREVISTA → SELECCIONADO → ONBOARDING INSERT INTO public.k_pipeline_stage (tenant_id, id_candidate, ds_stage, dt_stage_date, ds_notes, ds_created_by, fg_active, dt_creation_date) SELECT 'demo-corp', id_candidate, 'POSTULADO', NOW() - INTERVAL '30 days', 'Postulación espontánea vía OCC Mundial', 'rrhh@dch.mx', true, NOW() FROM public.k_candidate WHERE tenant_id = 'demo-corp' AND ds_email = 'candidato3.demo@yahoo.com';
INSERT INTO public.k_pipeline_stage (tenant_id, id_candidate, ds_stage, dt_stage_date, ds_notes, ds_created_by, fg_active, dt_creation_date) SELECT 'demo-corp', id_candidate, 'ENTREVISTA', NOW() - INTERVAL '25 days', 'Entrevista presencial exitosa. Excelente perfil técnico.', 'rrhh@dch.mx', true, NOW() FROM public.k_candidate WHERE tenant_id = 'demo-corp' AND ds_email = 'candidato3.demo@yahoo.com';
INSERT INTO public.k_pipeline_stage (tenant_id, id_candidate, ds_stage, dt_stage_date, ds_notes, ds_created_by, fg_active, dt_creation_date) SELECT 'demo-corp', id_candidate, 'SELECCIONADO', NOW() - INTERVAL '20 days', 'Seleccionada para el proyecto Bosch — inicio programado', 'rrhh@dch.mx', true, NOW() FROM public.k_candidate WHERE tenant_id = 'demo-corp' AND ds_email = 'candidato3.demo@yahoo.com';
INSERT INTO public.k_pipeline_stage (tenant_id, id_candidate, ds_stage, dt_stage_date, ds_notes, ds_created_by, fg_active, dt_creation_date) SELECT 'demo-corp', id_candidate, 'ONBOARDING', NOW() - INTERVAL '10 days', 'Expediente completo. Pendiente firma digital OTP para activación.', 'rrhh@dch.mx', true, NOW() FROM public.k_candidate WHERE tenant_id = 'demo-corp' AND ds_email = 'candidato3.demo@yahoo.com';

-- Documento 1: ISR mensual APROBADO INSERT INTO public.k_repse_document (tenant_id, id_repse_client, ds_period, ds_type, ds_status, ds_filename, ds_notes, ds_validated_by, dt_validated_date, fg_active, dt_creation_date) SELECT 'demo-corp', id_repse_client, TO_CHAR(CURRENT_DATE - INTERVAL '1 month', 'YYYY-MM'), 'ISR_MENSUAL', 'APROBADO', 'ISR_' || TO_CHAR(CURRENT_DATE - INTERVAL '1 month', 'YYYY_MM') || '.pdf', 'Declaración mensual ISR presentada en tiempo y forma', 'admin@dch.mx', NOW() - INTERVAL '5 days', true, NOW() FROM public.k_repse_client WHERE tenant_id = 'demo-corp' AND ds_rfc = 'CBM780901GH2';
-- Documento 2: IMSS SUA APROBADO INSERT INTO public.k_repse_document (tenant_id, id_repse_client, ds_period, ds_type, ds_status, ds_filename, ds_notes, ds_validated_by, dt_validated_date, fg_active, dt_creation_date) SELECT 'demo-corp', id_repse_client, TO_CHAR(CURRENT_DATE - INTERVAL '1 month', 'YYYY-MM'), 'IMSS_SUA', 'APROBADO', 'SUA_' || TO_CHAR(CURRENT_DATE - INTERVAL '1 month', 'YYYY_MM') || '.pdf', 'Pago cuota obrero-patronal IMSS-SUA liquidado puntualmente', 'admin@dch.mx', NOW() - INTERVAL '5 days', true, NOW() FROM public.k_repse_client WHERE tenant_id = 'demo-corp' AND ds_rfc = 'CBM780901GH2';
-- Documento 3: INFONAVIT APROBADO INSERT INTO public.k_repse_document (tenant_id, id_repse_client, ds_period, ds_type, ds_status, ds_filename, ds_notes, ds_validated_by, dt_validated_date, fg_active, dt_creation_date) SELECT 'demo-corp', id_repse_client, TO_CHAR(CURRENT_DATE - INTERVAL '1 month', 'YYYY-MM'), 'INFONAVIT', 'APROBADO', 'INFONAVIT_' || TO_CHAR(CURRENT_DATE - INTERVAL '1 month', 'YYYY_MM') || '.pdf', 'Aportaciones INFONAVIT y amortizaciones al corriente', 'admin@dch.mx', NOW() - INTERVAL '5 days', true, NOW() FROM public.k_repse_client WHERE tenant_id = 'demo-corp' AND ds_rfc = 'CBM780901GH2';
-- Semáforo de cumplimiento VERDE (5/6 documentos validados, 1 requerido pendiente del mes corriente) INSERT INTO public.k_repse_compliance (tenant_id, id_repse_client, ds_period, nb_documents_required, nb_documents_submitted, nb_documents_validated, nb_documents_rejected, ds_semaforo, fg_active, dt_creation_date) SELECT 'demo-corp', id_repse_client, TO_CHAR(CURRENT_DATE - INTERVAL '1 month', 'YYYY-MM'), 6, 6, 5, 0, 'VERDE', true, NOW() FROM public.k_repse_client WHERE tenant_id = 'demo-corp' AND ds_rfc = 'CBM780901GH2';

